int smb2_handle_write(unsigned int xid, struct cifs_io_parms *io_parms, unsigned int *nbytes,
                      struct kvec *iov, int n_vec) {
    struct smb2_write_request *req;
    struct smb2_write_response *resp;
    int rc = 0;
    int bytes_sent;

    /* Check if the connection is valid */
    if (!io_parms->cfile || !io_parms->cfile->ses || !io_parms->cfile->tcon) {
        return -EIO;
    }

    /* Allocate and prepare the request buffer */
    req = cifs_small_buf_get();
    if (!req) {
        return -ENOMEM;
    }

    /* Initialize the SMB2 write request header */
    init_smb2_write_request(req, xid, io_parms->pid, io_parms->tcon, io_parms->cfile,
                            iov, n_vec, *nbytes);

    /* Send the request and get the response */
    rc = cifs_send_recv(io_parms->cfile->ses, req, (char **)&resp, &bytes_sent, 0);
    if (rc != 0) {
        cifs_small_buf_release(req);
        return rc;
    }

    /* Update the number of bytes written from the response */
    *nbytes = le32_to_cpu(resp->DataOffset);

    /* Clean up the request buffer */
    cifs_small_buf_release(req);

    return 0;
}

int smb2_write(unsigned int xid, struct cifs_io_parms *io_parms, unsigned int *nbytes, struct kvec *iov, int n_vec) {
    struct smb2_write_request *req;
    struct smb2_write_response *resp;
    int rc = 0;
    int i;

    if (!io_parms || !iov || !nbytes || !n_vec) {
        return -EINVAL;
    }

    req = cifs_small_smb2_request_alloc(SMB2_WRITE_SIZE + n_vec * sizeof(struct kvec), GFP_NOFS);
    if (!req) {
        return -ENOMEM;
    }

    req->hdr.MessageID = cpu_to_le64(xid);
    req->PersistentFileId = io_parms->persistent_file_id;
    req->VolatileFileId = io_parms->volatile_file_id;
    req->Offset = cpu_to_le64(io_parms->offset);
    req->Remaining = 0;
    req->DataOffset = cpu_to_le16(SMB2_WRITE_SIZE);
    req->DataLength = cpu_to_le16(*nbytes);

    for (i = 0; i < n_vec; i++) {
        memcpy(req->iov[i].iov_base, iov[i].iov_base, iov[i].iov_len);
        req->iov[i].iov_len = iov[i].iov_len;
    }

    rc = cifs_send_recv(io_parms->tcon->ses->server, &req->hdr, &resp, 0);
    if (rc) {
        cifs_small_smb2_request_free(req);
        return rc;
    }

    *nbytes = le32_to_cpu(resp->DataLength);
    cifs_small_smb2_request_free(req);
    return rc;
}

int smb2_handle_write(unsigned int xid, struct cifs_io_parms *io_parms,
                      unsigned int *nbytes, struct kvec *iov, int n_vec) {
    int rc = 0;
    struct smb2_write_request *req = NULL;
    struct smb2_write_response *resp = NULL;
    struct kvec rsp_iov;

    if (!io_parms || !nbytes || !iov || n_vec <= 0)
        return -EINVAL;

    req = cifs_small_tcon_alloc(io_parms->tcon);
    if (!req)
        return -ENOMEM;

    req->hdr.MessageId = cpu_to_le64(xid);
    req->PersistentFileId = io_parms->persistent_fid;
    req->VolatileFileId = io_parms->volatile_fid;
    req->Offset = cpu_to_le64(io_parms->offset);
    req->Length = cpu_to_le32(*nbytes);
    req->ChunkCount = cpu_to_le16(n_vec);
    req->Remaining = 0;

    rc = cifs_send_recv(io_parms->tcon->ses->server,
                        iov, n_vec, &req->hdr, CIFS_WRITE_OP, &resp, &rsp_iov);
    if (rc) {
        cifs_small_tcon_free(req);
        return rc;
    }

    *nbytes = le32_to_cpu(resp->DataLength);
    cifs_small_tcon_free(req);
    return 0;
}

int smb2_handle_write(unsigned int xid, struct cifs_io_parms *io_parms, unsigned int *nbytes, struct kvec *iov, int n_vec) {
    int rc = 0;
    struct smb2_write_request *req = NULL;
    struct smb2_write_response *resp = NULL;
    struct TCP_Server_Info *server = io_parms->tcon->ses->server;

    if (!server || !serverCanDo(server, CIFS_NEGOTIATE_WRITE))
        return -EIO;

    req = kzalloc(sizeof(*req) + iov[0].iov_len, GFP_KERNEL);
    if (!req)
        return -ENOMEM;

    req->hdr.MessageId = cpu_to_le64(xid);
    req->PersistentFileId = io_parms->persistent_fid;
    req->VolatileFileId = io_parms->volatile_fid;
    req->Offset = cpu_to_le64(io_parms->offset);
    req->Remaining = 0;
    req->DataLength = cpu_to_le32(iov[0].iov_len);

    memcpy(req + 1, iov[0].iov_base, iov[0].iov_len);

    rc = cifs_send_recv(io_parms->tcon->ses, io_parms->tcon, (char *)req, CIFS_MAX_MSG_SIZE, &resp, 0);
    if (rc)
        goto out;

    *nbytes = le32_to_cpu(resp->DataOffset);
    rc = 0;

out:
    kfree(req);
    return rc;
}

int cifs_smb2_write(unsigned int xid, struct cifs_io_parms *io_parms, unsigned int *nbytes, struct kvec *iov, int n_vec) {
    struct smb2_write_req *req;
    struct smb2_write_rsp *rsp;
    int rc = 0;
    int resp_buftype;
    struct kveciov_hdr iov_hdr;
    unsigned int total_len;

    if (!io_parms || !nbytes || !iov || n_vec <= 0) {
        return -EINVAL;
    }

    req = smb2_plain_req_init(SMB2_WRITE, io_parms->tcon, &total_len, NULL);
    if (!req)
        return -ENOMEM;

    req->Offset = cpu_to_le64(io_parms->offset);
    req->Length = cpu_to_le32(io_parms->length);
    memcpy(req->PersistentFileId, io_parms->persistent_fid, 16);
    memcpy(req->VolatileFileId, io_parms->volatile_fid, 16);

    iov_hdr.iov = iov;
    iov_hdr.nvec = n_vec;
    iov_hdr.iov[0].iov_base = req;
    iov_hdr.iov[0].iov_len = total_len;
    iov_hdr.nvec++;

    rc = cifs_send_recv(xid, io_parms->tcon->ses, &iov_hdr, &rsp, &resp_buftype, CIFS_LOG_ERROR);
    if (rc != 0) {
        cifs_buf_release(req);
        return rc;
    }

    *nbytes = le32_to_cpu(rsp->DataOffset) + le32_to_cpu(rsp->DataLength);

    cifs_buf_release(req);
    cifs_buf_release(rsp);

    return 0;
}
